const canvas = wx.createCanvas();
const ctx = canvas.getContext('2d');
const { drawHud } = require('./js/hud');
function frame() { drawWorld(ctx); drawHud(ctx, score); requestAnimationFrame(frame); }
requestAnimationFrame(frame);

